import {options} from './business.js';
import {photography} from './photography.js';
export function showroomMarkup(path='/fleet'){
 const category=['Sedan','SUV','Sprinter'].find(c=>path.endsWith('/'+c.toLowerCase()))||'Sedan',photo=photography[category];
 return `<section class="private-showroom photographic-showroom" aria-labelledby="showroom-heading"><div class="showroom-topline"><div><span class="eyebrow">THE PRIVATE COLLECTION</span><h1 id="showroom-heading">A considered arrival.</h1></div><span class="collection-edition">MARTINEZ LOGISTICS LLC / CHAUFFEUR SERVICE</span></div><div class="showroom-experience"><div class="model-zone photo-zone"><div id="photo-host" class="photo-host" data-category="${category}"><img class="photo-atmosphere" src="${photo.src}" alt="" aria-hidden="true"><img class="vehicle-photo" src="${photo.src}" alt="${photo.alt}" fetchpriority="high" style="object-position:${photo.position}"></div><span class="photo-index" id="photo-index">01 / THE COLLECTION</span><p class="photo-caption">Representative vehicle photography. Your exact vehicle is confirmed when arranging your journey.</p><div class="model-booking-summary" hidden><span class="eyebrow">YOUR SELECTED CATEGORY</span><h2 id="compact-category">Luxury ${category}</h2><button class="text-button" type="button" id="change-vehicle">Change vehicle</button></div></div><aside class="showroom-copy"><span class="eyebrow" id="showroom-index">01 / 03</span><div class="selector category-tabs" role="group" aria-label="Vehicle category">${['Sedan','SUV','Sprinter'].map(c=>`<button type="button" data-showroom-category="${c}" aria-pressed="${c===category}">${c}</button>`).join('')}</div><div id="showroom-description" aria-live="polite"><h2>Luxury ${category}</h2><p>Choose the journey that suits you.</p></div><label for="showroom-service">Your service</label><select id="showroom-service">${options.map((o,i)=>`<option value="${i}">${o.name} — $${o.price.toFixed(2)}</option>`).join('')}</select><button type="button" class="button select-vehicle" id="select-vehicle">Reserve This Vehicle</button><div class="category-navigation"><button type="button" id="previous-vehicle">Previous</button><span class="category-rule" aria-hidden="true"></span><button type="button" id="next-vehicle">Next</button></div><a class="text-link understated" href="https://www.martinezlogisticsllc.com/appointments">View all booking options</a></aside><section class="reservation-panel" hidden aria-labelledby="reservation-heading"><button type="button" class="text-button" id="back-to-showroom">Return to the collection</button><span class="eyebrow">YOUR JOURNEY / PRIVATE RESERVATIONS</span><h2 id="reservation-heading" tabindex="-1">Every detail,<br>considered.</h2><p id="reservation-service-label"></p><label for="booking-service">Selected service</label><select id="booking-service">${options.map((o,i)=>`<option value="${i}">${o.name} — $${o.price.toFixed(2)}</option>`).join('')}</select><p class="caption">Choose an available time and complete your journey details in our live reservation calendar.</p><p class="caption" id="scheduler-status" role="status"></p><div id="scheduler-mount"></div><a id="external-booking" class="text-link" href="https://www.martinezlogisticsllc.com/appointments" target="_blank" rel="noopener noreferrer">Open booking in a new tab</a><p class="caption">Review the booking provider’s pricing and terms before confirming. Your payment details stay with the booking provider.</p></section></div><noscript><p class="notice"><a href="https://www.martinezlogisticsllc.com/appointments">Open the official reservation calendar</a> to choose your service and time.</p></noscript></section>`;
}
